const LEVELS=window.MAGIC_FOREST_LEVELS,KEY='magicForestSaveV2';
let save=JSON.parse(localStorage.getItem(KEY)||'null')||{unlocked:1,stars:{},items:[],crystals:0,sound:true,storySeen:false};
const app=document.querySelector('#app');let audio;
function persist(){localStorage.setItem(KEY,JSON.stringify(save))}
function tone(freq=520,d=.12){if(!save.sound)return;audio||=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
function topbar(back){return `<header class="topbar">${back?'<button class="icon-btn" data-back aria-label="ย้อนกลับ">‹</button>':''}<div class="brand"><img src="assets/items/golden-star.png" alt=""> ผจญภัยในป่าเวทมนตร์</div><div class="pill">💎 <b>${save.crystals}</b></div><button class="icon-btn" data-sound aria-label="เปิดหรือปิดเสียง">${save.sound?'🔊':'🔇'}</button></header>`}
function common(backFn=map){document.querySelector('[data-sound]')?.addEventListener('click',e=>{save.sound=!save.sound;persist();e.currentTarget.textContent=save.sound?'🔊':'🔇';tone()});document.querySelector('[data-back]')?.addEventListener('click',backFn)}
function characterArt(who,fallback,extra=''){if(who.includes('ชิป')&&who.includes('ฟลัฟฟี่'))return `<span class="character-pair"><img src="assets/characters/chip.png" alt="ชิป"><img src="assets/characters/fluffy.png" alt="ฟลัฟฟี่"></span>`;if(who.includes('แบมแบม'))return `<img class="character-art ${extra}" src="assets/characters/bambam.png" alt="แบมแบม นักผจญภัยตัวน้อย">`;if(who.includes('ชิป'))return `<img class="character-art ${extra}" src="assets/characters/chip.png" alt="ชิป กระรอกผู้ช่วยของแบมแบม">`;if(who.includes('ฟลัฟฟี่'))return `<img class="character-art ${extra}" src="assets/characters/fluffy.png" alt="ฟลัฟฟี่ กระต่ายนักผจญภัย">`;if(who.includes('ต้นไม้'))return `<img class="character-art ${extra}" src="assets/characters/silver-tree.png" alt="ต้นไม้สีเงินผู้พิทักษ์ป่าเวทมนตร์">`;if(who.includes('พ่อมด'))return `<img class="character-art ${extra}" src="assets/characters/shadow-wizard.png" alt="พ่อมดเงาจอมเจ้าเล่ห์">`;if(fallback==='🌙')return `<img class="character-art ${extra}" src="assets/items/moon.png" alt="ดวงจันทร์เวทมนตร์">`;return fallback}
function starRating(stars){return `<span class="rating-stars" aria-label="${stars} ดาว">${Array.from({length:3},(_,i)=>`<img class="${i<stars?'earned':'empty'}" src="assets/items/golden-star.png" alt="">`).join('')}</span>`}
const PROLOGUE=[
 {who:'ผู้เล่า',face:'🌙',text:'ค่ำวันหนึ่ง หลังเสียงระฆังโรงเรียนดัง แบมแบมได้ยินเสียงกระซิบมาจากป่าที่ไม่เคยมีใครกล้าเข้าไป'},
 {who:'แบมแบม',face:'🧒🏻',text:'เสียงนั้น… กำลังนับเลขอยู่หรือเปล่านะ? หนึ่ง… สอง… แล้วทำไมถึงหยุดล่ะ?'},
 {who:'ต้นไม้สีเงิน',face:'🌳',text:'ผู้ที่ได้ยินเสียงของตัวเลข โปรดช่วยข้าด้วย หัวใจแห่งตัวเลขกำลังแตกสลาย!'},
 {who:'ชิป',face:'🐿️',text:'ว้าย! เธอได้ยินจริง ๆ ด้วย ฉันชื่อชิป พ่อมดเงาขโมยผลึกไป ถ้าเราไม่รีบ ป่าทั้งผืนจะลืมวิธีนับ!'},
 {who:'แบมแบม',face:'🧒🏻',text:'งั้นเราไปเอาตัวเลขกลับมากันเถอะ ต่อให้มีหนึ่งร้อยปริศนา ฉันก็ไม่ถอย!'}
];
function home(){app.innerHTML=`<section class="screen">${topbar()}<div class="hero"><div class="intro"><div class="eyebrow">บทที่ 1 · เสียงกระซิบจากต้นไม้สีเงิน</div><h1>หัวใจแห่ง<br>ตัวเลขหายไป!</h1><p>เมื่อป่าเริ่มลืมวิธีนับ แบมแบมต้องร่วมมือกับชิปและฟลัฟฟี่ ตามหาผลึกที่ถูกพ่อมดเงาขโมยไป</p><div class="actions"><button class="primary" id="start">${save.storySeen?'เดินทางต่อ':'เปิดเรื่องราว'}</button><button class="secondary" id="mapBtn"><img class="button-item" src="assets/items/adventure-map.png" alt=""> แผนที่</button></div><div class="inventory">${save.items.length?save.items.map(x=>`<span class="item">${x}</span>`).join(''):'<span class="item">🎒 กระเป๋านักผจญภัย</span>'}</div></div><div class="companions"><div class="avatar art-avatar hero-player">${characterArt('แบมแบม','🧒🏻')}<small>แบมแบม</small></div><div class="avatar art-avatar">${characterArt('ชิป','🐿️')}<small>ชิป</small></div><div class="avatar art-avatar">${characterArt('ฟลัฟฟี่','🐇')}<small>ฟลัฟฟี่</small></div></div></div></section>`;common();start.onclick=()=>save.storySeen?map():story(PROLOGUE,()=>{save.storySeen=true;persist();map()});mapBtn.onclick=map}
function story(lines,done,i=0){const line=lines[i];app.innerHTML=`<section class="story-screen">${topbar(true)}<div class="story-stage"><img class="story-magic" src="assets/items/golden-star.png" alt="ประกายเวทมนตร์"><div class="speaker-face">${characterArt(line.who,line.face)}</div><div class="dialogue"><div class="speaker">${line.who}</div><p>${line.text}</p><button class="primary" id="nextLine">${i===lines.length-1?'ออกเดินทาง':'ต่อไป'}</button></div><div class="skip" id="skip">ข้ามเรื่องราว</div></div></section>`;common(home);nextLine.onclick=()=>{tone(480+i*40);i<lines.length-1?story(lines,done,i+1):done()};skip.onclick=done}
function map(){app.innerHTML=`<section class="screen">${topbar()}<div class="map-wrap"><div class="map-head"><div><div class="eyebrow">เส้นทางตามหาผลึกชิ้นแรก</div><h1>World 1 · ป่าแห่งตัวเลข</h1><p>ทุกสถานที่มีความลับซ่อนอยู่ ลองสำรวจก่อนใช้พลังคณิตศาสตร์</p></div><button class="secondary" id="homeBtn">บ้านต้นไม้</button></div><div class="stage-grid">${LEVELS.map(l=>{const locked=l.id>save.unlocked,stars=save.stars[l.id]||0;return `<button class="stage ${locked?'locked':''} ${stars?'done':''}" data-level="${l.id}" ${locked?'disabled':''}><span class="num">ตอนที่ ${l.id} ${locked?'· 🔒':''}</span><span class="emoji">${l.icon}</span><h2>${l.title}</h2><p>${l.teaser}</p>${starRating(stars)}</button>`}).join('')}</div></div></section>`;common();homeBtn.onclick=home;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>beginLevel(+b.dataset.level))}
function beginLevel(id){const l=LEVELS[id-1];story(l.dialogue,()=>explore(id))}
function explore(id){const l=LEVELS[id-1],found=new Set();app.innerHTML=`<section class="explore ${l.scene}">${topbar(true)}<div class="quest-card"><span>ภารกิจ</span><strong>${l.quest}</strong></div><div class="explore-copy"><div class="eyebrow">ตอนที่ ${l.id}</div><h1>${l.title}</h1><p>${l.exploreText}</p></div><div class="hotspots">${l.hotspots.map((h,n)=>`<button class="hotspot" data-spot="${n}" aria-label="สำรวจ ${h.label}"><span>${h.icon}</span><small>${h.label}</small></button>`).join('')}</div><div class="clue-box" id="clue">${characterArt('ชิป','🐿️','clue-character')}<p>ชิป: ลองแตะสิ่งที่น่าสงสัยในฉากดูสิ!</p></div><button class="primary solve-btn" id="solve" disabled>ใช้พลังตัวเลข</button></section>`;common(map);document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{const n=+b.dataset.spot,h=l.hotspots[n];if(found.has(n))return;found.add(n);b.classList.add('found');clue.innerHTML=`<span>${h.icon}</span><p><strong>${h.label}</strong><br>${h.clue}</p>`;tone(560+n*70);if(found.size>=l.required){solve.disabled=false;solve.textContent='ใช้พลังตัวเลข ✦'}});solve.onclick=()=>play(id)}
function play(id){const l=LEVELS[id-1];let tries=0,digits='',wheels=[6,0,0],echoValue=732,echoSteps=0,wingLight=0,litButterflies=0;app.innerHTML=`<section class="play">${topbar(true)}<div class="play-area"><article class="mission"><div class="eyebrow">เวทมนตร์แห่งตัวเลข · ตอนที่ ${l.id}</div><div class="scene-icon">${l.icon}</div><h1>${l.puzzleTitle}</h1><p class="story">${l.story}</p><div class="prompt">${l.prompt}</div><div class="puzzle" id="puzzle"></div><div class="feedback" id="feedback"></div></article></div></section>`;common(()=>explore(id));const p=document.querySelector('#puzzle'),fb=document.querySelector('#feedback');const check=v=>{tries++;if(String(v)===String(l.answer)){tone(760,.3);finish(l,tries)}else{tone(180,.18);fb.textContent=tries===1?l.hint1:l.hint2;navigator.vibrate?.(60)}};
if(l.type==='drag'){p.innerHTML=l.choices.map(x=>`<button draggable="true" class="tile" data-v="${x}">${x}</button>`).join('')+'<div class="slot" tabindex="0">วงแหวนเวท</div>';const slot=p.querySelector('.slot');p.querySelectorAll('.tile').forEach(t=>{t.ondragstart=e=>e.dataTransfer.setData('text',t.dataset.v);t.onclick=()=>check(t.dataset.v)});slot.ondragover=e=>e.preventDefault();slot.ondrop=e=>{e.preventDefault();check(e.dataTransfer.getData('text'))}}
if(l.type==='digits'){p.innerHTML='<div class="slot" id="display">_ _ _</div>'+l.choices.map(x=>`<button class="tile" data-v="${x}">${x}</button>`).join('')+'<button class="choice" id="clear">ล้าง</button>';p.querySelectorAll('.tile').forEach(t=>t.onclick=()=>{if(digits.length<3){digits+=t.dataset.v;display.textContent=digits.split('').join(' ');tone(420+digits.length*80);if(digits.length===3)setTimeout(()=>check(digits),180)}});clear.onclick=()=>{digits='';display.textContent='_ _ _'}}
if(l.type==='counter'){const labels=['หลักร้อย','หลักสิบ','หลักหน่วย'];p.innerHTML=`<div class="number-wheels">${wheels.map((v,i)=>`<div class="wheel"><small>${labels[i]}</small><button data-wheel="${i}" data-dir="1" aria-label="เพิ่ม${labels[i]}">+</button><strong id="wheel${i}">${v}</strong><button data-wheel="${i}" data-dir="-1" aria-label="ลด${labels[i]}">−</button></div>`).join('')}<div class="wheel-total">พลังรวม <strong id="total">600</strong></div></div><button class="primary" id="cast">ร่ายเวทหยุดเพลง</button>`;document.querySelectorAll('[data-wheel]').forEach(b=>b.onclick=()=>{const i=+b.dataset.wheel,dir=+b.dataset.dir;wheels[i]=(wheels[i]+dir+10)%10;document.querySelector('#wheel'+i).textContent=wheels[i];total.textContent=wheels[0]*100+wheels[1]*10+wheels[2];tone(420+i*90)});cast.onclick=()=>check(wheels[0]*100+wheels[1]*10+wheels[2])}
if(l.id===4){const parts=[{v:200,label:'สองร้อยหยด'},{v:80,label:'แปดสิบหยด'},{v:9,label:'เก้าหยด'}];p.innerHTML=`<div class="echo-cave"><img src="assets/characters/cave-bird.png" alt="นกถ้ำที่ดื่มน้ำค้าง"><div class="echo-pool"><small>น้ำค้างที่ยังส่องแสง</small><strong id="echoTotal">732</strong><span id="echoTrail">เริ่มจาก 732 หยด</span></div></div><div class="echo-stones">${parts.map((part,i)=>`<button class="echo-stone" data-subtract="${part.v}" data-index="${i}"><span>−${part.v}</span><small>${part.label}</small></button>`).join('')}</div><button class="primary" id="revealEcho" disabled>เปิดประตูเสียงจริง</button>`;document.querySelectorAll('[data-subtract]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('heard');echoValue-=+b.dataset.subtract;echoSteps++;echoTotal.textContent=echoValue;echoTrail.textContent+=` − ${b.dataset.subtract}`;tone(600-echoSteps*80,.22);if(echoSteps===parts.length){revealEcho.disabled=false;fb.textContent='เสียงสะท้อนที่พูดจริงเริ่มเปล่งแสงแล้ว!'}});revealEcho.onclick=()=>check(echoValue)}
if(l.id===5){p.innerHTML=`<div class="boss-stage"><div class="shadow-vines" aria-hidden="true">🕸️</div><div class="wing-meter"><small>พลังแสงจากปีก</small><strong><span id="wingCount">0</span> / 18</strong><div><i id="wingBar"></i></div></div></div><div class="butterfly-swarm">${Array.from({length:9},(_,i)=>`<button class="light-butterfly" data-butterfly="${i}" aria-label="ปลุกผีเสื้อตัวที่ ${i+1}"><img src="assets/characters/light-butterfly.png" alt=""><small>+2 ปีก</small></button>`).join('')}</div><button class="primary final-spell" id="finalSpell" disabled>ปล่อยคาถาแสง 18 ปีก!</button>`;document.querySelectorAll('[data-butterfly]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('lit');litButterflies++;wingLight+=2;wingCount.textContent=wingLight;wingBar.style.width=`${wingLight/18*100}%`;tone(440+litButterflies*38,.18);if(litButterflies===9){finalSpell.disabled=false;fb.textContent='ผีเสื้อทั้ง 9 ตัวพร้อมแล้ว—ปล่อยพลังจากปีก 18 ข้าง!'}});finalSpell.onclick=()=>check(wingLight)}
if(l.type==='choice'&&l.id!==4&&l.id!==5){p.innerHTML=l.choices.map(x=>`<button class="choice" data-v="${x}">${x}</button>`).join('');p.querySelectorAll('.choice').forEach(c=>c.onclick=()=>check(c.dataset.v))}}
function finish(l,tries){const stars=tries===1?3:tries<=3?2:1;save.stars[l.id]=Math.max(save.stars[l.id]||0,stars);save.unlocked=Math.min(LEVELS.length,Math.max(save.unlocked,l.id+1));if(!save.items.includes(l.item+' '+l.reward)){save.items.push(l.item+' '+l.reward);save.crystals+=10}persist();app.insertAdjacentHTML('beforeend',`<div class="reward"><div class="reward-card"><div class="reward-burst">${l.item}</div>${starRating(stars)}<h2>${l.successTitle}</h2><p>${l.success}</p><div class="loot">ได้รับ “${l.reward}” · 💎 +10</div><button class="primary" id="next">${l.id===LEVELS.length?'ดูตอนจบ World 1':'เดินทางต่อ'}</button></div></div>`);next.onclick=()=>l.id<LEVELS.length?map():story(window.WORLD_ONE_ENDING,map)}
home();
